package com.ivorama.nlp.transform;
import com.ivorama.nlp.core.*;import org.junit.jupiter.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class MorphologyIntegrationTest {
 private static FrenchNlpAnalyzer analyzer;
 @BeforeAll static void init(){analyzer=new FrenchNlpAnalyzer();}
 private static final TransformationConfig PLAIN=new TransformationConfig(false,true,false,false,false,false,false,false,9);
 private SynonymProvider edited(String source,String candidate){return new SynonymProvider(){public Optional<String> synonym(TokenData t,SynonymRegister r){return t.word().equalsIgnoreCase(source)?Optional.of(candidate):Optional.empty();}public boolean isCuratedCandidate(TokenData t,SynonymRegister r,String c){return t.word().equalsIgnoreCase(source)&&c.equals(candidate);}};}
 @Test void genderChangeUsesAttestedArticle(){var r=new SentenceTransformerService(analyzer,edited("rivière","fleuve")).transform("La rivière traverse la vallée.",PLAIN);assertEquals("Le fleuve traverse la vallée.",r.transformed());assertTrue(r.replacements().stream().anyMatch(e->e.original().equals("La")&&e.replacement().equals("Le")));}
 @Test void pluralIsInflectedRatherThanSuffixGuessed(){var r=new SentenceTransformerService(analyzer,edited("rivière","fleuve")).transform("Les rivières traversent les vallées.",PLAIN);assertEquals("Les fleuves traversent les vallées.",r.transformed());}
 @Test void dependentAdjectivesAgreeAtomically(){var r=new SentenceTransformerService(analyzer,edited("rivière","fleuve")).transform("La longue rivière tranquille traverse la vallée.",PLAIN);assertEquals("Le long fleuve tranquille traverse la vallée.",r.transformed());}
 @Test void copularPredicateAgreesWithChangedSubject(){var r=new SentenceTransformerService(analyzer,edited("rivière","fleuve")).transform("La rivière est longue.",PLAIN);assertEquals("Le fleuve est long.",r.transformed());}
 @Test void coordinatedDependentAdjectivesAgreeTogether(){var r=new SentenceTransformerService(analyzer,edited("rivière","fleuve")).transform("La petite rivière large et sinueuse traverse la vallée.",PLAIN);assertEquals("Le petit fleuve large et sinueux traverse la vallée.",r.transformed());}
 @Test void missingMorphologyAbstains(){var a=analyzer.analyzeFirstSentence("La rivière traverse la vallée.");var r=new SentenceTransformerEngine(edited("rivière","fleuve"),new ConservativeMorphologicalEngine()).transform(a,PLAIN);assertEquals(a.originalText(),r.transformed());}
 @Test void properNounDoesNotConsumeCommonNounOrdinal(){var a=analyzer.analyzeFirstSentence("Marie regarde la rivière.");var r=new SentenceTransformerEngine(edited("rivière","fleuve")).transform(a,PLAIN);assertTrue(r.transformed().contains("le fleuve"));assertTrue(r.transformed().startsWith("Marie"));}
 @Test void noOpPreservesExactQuotationAndSpaces(){String s="«  Lyon : une enquête ?  »";var r=new SentenceTransformerService(analyzer,(t,reg)->Optional.empty()).transformText(s,PLAIN);assertEquals(s,r.transformed());}
 @Test void firstSentenceDoesNotAppendRestOfText(){var a=analyzer.analyzeFirstSentence("Le visiteur arrive. La porte est ouverte.");assertEquals("Le visiteur arrive.",a.originalText());}
 @Test void sourceFeaturesAndDependenciesAreAttested(){var a=analyzer.analyzeFirstSentence("Les rivières paisibles coulent.");var t=a.tokens().stream().filter(x->x.word().equals("rivières")).findFirst().orElseThrow();assertEquals("rivière",t.lemma());assertEquals("fem",t.gender());assertEquals("pl",t.number());assertTrue(t.headIndex()>0);assertTrue(t.beginOffset()>=0);}
 @Test void decomposedUnicodeUsesSameLexicalEvidence(){String word=java.text.Normalizer.normalize("rivière",java.text.Normalizer.Form.NFD);assertEquals("rivière",new LexiconMorphologicalEngine().analyze(new TokenData(1,word,"NOUN")).lemma());}
 @Test void satisfiedCommaPolicyIsNotReportedAsAnExtraEdit(){var r=new SentenceTransformerEngine(new ResourceSynonymProvider()).transform(TestFixtures.richSentence(),new TransformationConfig(true,true,true,true,true,true,true,false,20261107L));assertTrue(r.appliedRules().contains("respiration_cool_mode"));var c=r.executions().stream().filter(x->x.parameter().equals("commas")).findFirst().orElseThrow();assertEquals("ALREADY_SATISFIED",c.status());assertEquals(0,c.applications());}
 @Test void injectedEmptyPipelineCannotBypassMorphology(){var a=analyzer.analyzeFirstSentence("La rivière traverse la vallée.");var e=new SentenceTransformerEngine(edited("rivière","zzinconnuq"),new ValidationPipeline(List.of()));assertEquals(a.originalText(),e.transform(a,PLAIN).transformed());}
 @Test void untrustedProviderCannotBypassSemantics(){var a=analyzer.analyzeFirstSentence("Une équipe travaille.");assertEquals(a.originalText(),new SentenceTransformerEngine((t,r)->Optional.of("cabine")).transform(a,PLAIN).transformed());}
}
